CREATE TABLE public.event_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.families(id), record_id uuid NOT NULL, actor_id uuid NOT NULL, actor_name text NOT NULL DEFAULT '', action text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.event_history TO authenticated; GRANT ALL ON public.event_history TO service_role;
ALTER TABLE public.event_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY history_read ON public.event_history FOR SELECT TO authenticated USING(public.family_access(family_id));
CREATE FUNCTION public.audit_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.kind='event' THEN INSERT INTO public.event_history(family_id,record_id,actor_id,actor_name,action,snapshot) VALUES(NEW.family_id,NEW.id,auth.uid(),coalesce((SELECT display_name FROM public.profiles WHERE id=auth.uid()),''),CASE WHEN TG_OP='INSERT' THEN 'eklendi' ELSE 'düzenlendi' END,NEW.payload); END IF; RETURN NEW; END $$;
CREATE TRIGGER event_audit AFTER INSERT OR UPDATE ON public.family_records FOR EACH ROW EXECUTE FUNCTION public.audit_event();
CREATE OR REPLACE FUNCTION public.join_family(code uuid,parent text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE fid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT id INTO fid FROM public.families WHERE invite_code=code FOR UPDATE; IF fid IS NULL THEN RAISE EXCEPTION 'Invalid invitation'; END IF; IF (SELECT count(*) FROM public.user_roles WHERE family_id=fid)>=2 THEN RAISE EXCEPTION 'Family already has two parents'; END IF; INSERT INTO public.user_roles(family_id,user_id,parent_role,access,display_name) SELECT fid,auth.uid(),parent,'editor',display_name FROM public.profiles WHERE id=auth.uid(); RETURN fid; END $$;